// Управление нагрузкой через MOSFET-модуль IRF520
// Включение на 10 секунд каждые 10 минут

const uint8_t MOSFET_PIN = 3;              // Пин управления затвором

const unsigned long ON_TIME_MS   = 10UL * 1000UL;    // 10 секунд
const unsigned long CYCLE_TIME_MS = 10UL * 60UL * 1000UL; // 10 минут

unsigned long cycleStart = 0;

void setup() {
  pinMode(MOSFET_PIN, OUTPUT);
  digitalWrite(MOSFET_PIN, LOW);   // Изначально выключено
  cycleStart = millis();
}

void loop() {
  unsigned long elapsed = millis() - cycleStart;

  if (elapsed < ON_TIME_MS) {
    // Первые 10 секунд цикла — нагрузка включена
    digitalWrite(MOSFET_PIN, HIGH);
  } else {
    // Остальное время — выключена
    digitalWrite(MOSFET_PIN, LOW);
  }

  // Начало нового цикла
  if (elapsed >= CYCLE_TIME_MS) {
    cycleStart += CYCLE_TIME_MS;   // без накопления ошибки
  }
}
